function fewestSlides(board: number[][]): number {
  const goal = "123450";
  const start = board.flat().join("");
  const adj = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
  const seen = new Set([start]);
  let level = [start];
  for (let moves = 0; level.length; moves++) {
    const next: string[] = [];
    for (const s of level) {
      if (s === goal) return moves;
      const z = s.indexOf("0");
      for (const w of adj[z]) {
        const a = s.split("");
        [a[z], a[w]] = [a[w], a[z]];
        const t = a.join("");
        if (!seen.has(t)) { seen.add(t); next.push(t); }
      }
    }
    level = next;
  }
  return -1;
}

