function fewestSlides(board: number[][]): number {
  const flat = board.flat();
  const tiles = flat.filter(x => x !== 0);
  let inv = 0;
  for (let i = 0; i < tiles.length; i++)
    for (let j = i + 1; j < tiles.length; j++) if (tiles[i] > tiles[j]) inv++;
  if (inv % 2 === 1) return -1;
  const adj = [[1, 3], [0, 2, 4], [1, 5], [0, 4], [1, 3, 5], [2, 4]];
  const dist = new Map<string, number>([["123450", 0]]);
  const queue = ["123450"];
  for (let h = 0; h < queue.length; h++) {
    const s = queue[h], z = s.indexOf("0");
    for (const w of adj[z]) {
      const a = s.split("");
      [a[z], a[w]] = [a[w], a[z]];
      const t = a.join("");
      if (!dist.has(t)) { dist.set(t, dist.get(s)! + 1); queue.push(t); }
    }
  }
  return dist.get(flat.join("")) ?? -1;
}

